const rawText =
  $json.validated_recommendation ??
  $json.output?.[0]?.content?.[0]?.text ??
  $json.text ??
  '';

const movie = $('Select Best Movie').first().json;

if (!movie.poster_path) {
  throw new Error('The selected movie does not have a poster.');
}

const caption = String(rawText).trim();

if (!caption) {
  throw new Error('No validated recommendation was provided.');
}

return [{
  json: {
    caption,
    photo_url: `https://image.tmdb.org/t/p/w780${movie.poster_path}`,
    movie_id: movie.id,
    title: movie.title,
    release_date: movie.release_date,
    vote_average: movie.vote_average,
    vote_count: movie.vote_count,
    quality_score: movie.quality_score,
    validation_status: $json.validation_status ?? 'passed'
  }
}];

const movies = $input.all();

const validMovies = movies.filter(item => {
  const movie = item.json;

  return (
    movie.id &&
    movie.title?.trim() &&
    movie.overview?.trim() &&
    movie.poster_path &&
    movie.release_date &&
    Number(movie.vote_average) > 0 &&
    Number(movie.vote_count) > 0
  );
});

if (validMovies.length === 0) {
  throw new Error(
    'No valid movies found. Try adjusting the TMDB filters in Workflow Settings.'
  );
}

return validMovies;

const items = $input.all();

const settings = $('Workflow Settings').first().json;
const minRating = Number(settings.min_rating ?? 6.5);

const maxPopularity = Math.max(
  ...items.map(item => Number(item.json.popularity) || 0),
  1
);

const scored = items.map(item => {
  const movie = item.json;

  const rating = Number(movie.vote_average) || 0;
  const votes = Number(movie.vote_count) || 0;
  const popularity = Number(movie.popularity) || 0;

  // Rating: up to 50 points
  const ratingNormalized = Math.max(
    0,
    Math.min(1, (rating - minRating) / (10 - minRating))
  );
  const ratingScore = ratingNormalized * 50;

  // Vote count: up to 30 points
  const votesScore =
    Math.min(Math.log10(votes + 1) / 5, 1) * 30;

  // Popularity relative to other candidates: up to 20 points
  const popularityScore =
    Math.min(popularity / maxPopularity, 1) * 20;

  const qualityScore =
    ratingScore + votesScore + popularityScore;

  return {
    ...item,
    json: {
      ...movie,
      quality_score: Number(qualityScore.toFixed(2)),
      score_rating: Number(ratingScore.toFixed(2)),
      score_votes: Number(votesScore.toFixed(2)),
      score_popularity: Number(popularityScore.toFixed(2))
    }
  };
});

scored.sort(
  (a, b) => b.json.quality_score - a.json.quality_score
);

return scored;

const movies = $input.all();

if (movies.length === 0) {
  throw new Error(
    'No scored movie candidates found. Try adjusting Workflow Settings.'
  );
}

// Persistent workflow history
const staticData = $getWorkflowStaticData('global');

const publishedIds = new Set(
  (staticData.published_movie_ids ?? []).map(String)
);

// Score Movie Candidates has already sorted movies
// from highest quality_score to lowest.
const unseenMovies = movies.filter(
  item => !publishedIds.has(String(item.json.id))
);

if (unseenMovies.length === 0) {
  throw new Error(
    'All current movie candidates have already been published. ' +
    'Try increasing random_page_max or adjusting the movie filters.'
  );
}

const bestMovie = unseenMovies[0];

return [{
  json: {
    ...bestMovie.json,
    dedupe_status: 'new',
    candidates_total: movies.length,
    candidates_unseen: unseenMovies.length
  }
}];

const items = $input.all();

return items.map(item => {
  const rawText =
    item.json.output?.[0]?.content?.[0]?.text ??
    item.json.text ??
    '';

  const recommendation = String(rawText).trim();

  if (!recommendation) {
    throw new Error('OpenAI returned an empty recommendation.');
  }

  if (recommendation.length < 40) {
    throw new Error(
      'The generated recommendation is too short. Please retry the workflow.'
    );
  }

  if (recommendation.length > 900) {
    throw new Error(
      'The generated recommendation is too long for a Telegram photo caption.'
    );
  }

  const hashtags = recommendation.match(/#[\p{L}\p{N}_]+/gu) ?? [];

  if (hashtags.length !== 3) {
    throw new Error(
      `Expected exactly 3 hashtags, but received ${hashtags.length}.`
    );
  }

  return {
    json: {
      ...item.json,
      validated_recommendation: recommendation,
      validation_status: 'passed',
      hashtag_count: hashtags.length
    }
  };
});

const staticData = $getWorkflowStaticData('global');

const movie = $('Prepare Telegram Post').first().json;
const settings = $('Workflow Settings').first().json;

const movieId = String(movie.movie_id);
const historyLimit = Number(settings.history_limit ?? 200);

if (!staticData.published_movie_ids) {
  staticData.published_movie_ids = [];
}

// Add only if it isn't already stored
if (!staticData.published_movie_ids.includes(movieId)) {
  staticData.published_movie_ids.push(movieId);
}

// Keep only the most recent IDs
if (staticData.published_movie_ids.length > historyLimit) {
  staticData.published_movie_ids =
    staticData.published_movie_ids.slice(-historyLimit);
}

return [{
  json: {
    status: 'published_and_remembered',
    movie_id: movie.movie_id,
    title: movie.title,
    quality_score: movie.quality_score,
    history_size: staticData.published_movie_ids.length
  }
}];
